export const grades=['LKG','UKG'];
export const subjectMap={english:{en:'English',hi:'अंग्रेज़ी',icon:'🔤'},hindi:{en:'Hindi',hi:'हिंदी',icon:'अ'},math:{en:'Maths',hi:'गणित',icon:'🔢'},world:{en:'Our World',hi:'हमारे आसपास',icon:'🌱'},art:{en:'Art & Play',hi:'कला व खेल',icon:'🎨'}};
export const clampPoint=(x,y)=>[Math.max(0,Math.min(800,x)),Math.max(0,Math.min(500,y))];
export const countGroups=n=>{if(!Number.isInteger(n)||n<0||n>50)throw Error('Count must be an integer from 0 to 50');return Array.from({length:Math.ceil(n/10)},(_,i)=>Math.min(10,n-i*10))};
export const firstTryScore=attempts=>Object.values(attempts).filter(a=>a.firstCorrect).length;
export function recordAnswer(attempts,index,choice,correct){const previous=attempts[index];if(previous?.solved)return attempts;return{...attempts,[index]:{firstCorrect:previous?previous.firstCorrect:choice===correct,solved:choice===correct||!!previous?.solved,selected:choice}}}
export function shapeSvg(shape,color='#32765a'){if(!/^#[a-f0-9]{6}$/i.test(color))color='#32765a';const paths={circle:'<circle cx="120" cy="95" r="70"/>',square:'<rect x="50" y="25" width="140" height="140" rx="2"/>',rectangle:'<rect x="20" y="45" width="200" height="100" rx="2"/>',triangle:'<path d="M120 18 220 170H20Z"/>',flower:'<path d="M120 105V180" fill="none" stroke="#32765a" stroke-width="6"/><circle cx="95" cy="60" r="26"/><circle cx="145" cy="60" r="26"/><circle cx="80" cy="100" r="26"/><circle cx="160" cy="100" r="26"/><circle cx="105" cy="135" r="26"/><circle cx="135" cy="135" r="26"/><circle cx="120" cy="95" r="27" fill="#e8bd42"/>',star:'<path d="m120 12 24 55 60 6-45 41 13 61-52-31-52 31 13-61-45-41 60-6Z"/>'};return `<svg viewBox="0 0 240 190" aria-hidden="true"><g fill="${color}" stroke="#294434" stroke-width="3">${paths[shape]||paths.circle}</g></svg>`}

export function arithmeticResult(a,b,op){if(!Number.isInteger(a)||!Number.isInteger(b)||a<0||b<0)throw Error('Use whole nonnegative amounts');if(op==='subtract'){if(a>10||b>a)throw Error('Take away no more than the starting amount');return a-b}if(op!=='add'||a>5||b>5)throw Error('Addition amounts are from 0 to 5');return a+b}

export const positionPoint=position=>({inside:[130,120],outside:[220,120],above:[130,30],below:[130,210]})[position]||[130,120];
export function positionSvg(position){const [x,y]=positionPoint(position);return `<svg viewBox="0 0 280 240" aria-hidden="true"><rect x="80" y="70" width="100" height="100" rx="8" fill="#dfead4" stroke="#294434" stroke-width="4"/><circle cx="${x}" cy="${y}" r="16" fill="#bf4439" stroke="#6f2b24" stroke-width="2"/></svg>`}
export function comparisonSvg(groups){return `<svg viewBox="0 0 280 200" aria-hidden="true">${groups.map((n,k)=>`<rect x="${15+k*145}" y="15" width="115" height="170" rx="15" fill="#edf1e6" stroke="#607f68"/>${Array.from({length:n},(_,i)=>`<circle cx="${40+k*145+(i%3)*30}" cy="${60+Math.floor(i/3)*50}" r="10" fill="${k?'#3c69a9':'#235a45'}"/>`).join('')}`).join('')}</svg>`}
